          "«Что я выбираю свободно, а что делаю из страха потерять другого?»",
          "«Как сохранить связь с другим, не оставляя себя?»",
          "Возвращаю способность договариваться там, где возможен компромисс, и обозначать границу там, где компромисс требует отказа от чего-то для меня существенного.",
          "Мне не обязательно выбирать между собой и отношениями каждый раз, когда наши желания различаются.",
