          "«Я отвечаю за то, чтобы все поступали правильно».",
          "«Власть означает право решать за других».",
          "Проявляю цикл:",
          "страх хаоса ↔ усиление контроля;\nчужая свобода ↔ ощущение угрозы;\nсопротивление других ↔ еще большее давление;\nвласть ↔ необходимость подчинения."
