          "порядок = тотальный контроль;\nвласть = подавление;\nнесогласие = неповиновение;\nдругой способ = неправильный способ;\nошибка другого = моя ответственность;\nсвобода = хаос;\nправило = истина;\nруководить = распоряжаться людьми;\nотказ подчиняться = неуважение;\nконтроль = безопасность.",
