          "Я выбираю беречь отношения, а не удерживать человека.",
          "Я могу вкладываться в близость, создавать доверие, говорить о потребностях, поддерживать связь и защищать важные для отношений договоренности.",
          "Мне можно хотеть быть выбранной.",
