          "Проявляю решения:",
          "«Правду можно получить только через давление».",
          "«Если все спокойно, значит, настоящее скрывают».",
          "«Чтобы меня услышали, нужно довести ситуацию до предела».",
          "«Сильная реакция означает настоящие чувства».",
          "«Если я вызову конфликт, я наконец узнаю правду».",
          "«Чтобы запустить изменения, нужно разрушить спокойствие».",
          "Проявляю цикл:",
          "скрытое напряжение ↔ провокация;\nпровокация ↔ сильная реакция;\nреакция ↔ подтверждение значимости;\nзащита другого ↔ еще большее давление."
