          "Освобождаю связки:",
          "конфликт = правда;\nсильная реакция = искренность;\nзлость = небезразличие;\nпровокация = способ получить ответ;\nспокойствие = сокрытие;\nнапряжение = близость;\nкризис = изменение;\nчужая реакция = доказательство моей значимости;\nдавление = движение;\nэмоциональный взрыв = ясность.",
          "Мне не нужно разрушать спокойствие только для того, чтобы проверить, настоящее ли оно.",
